function installPlatform(){var ua=navigator.userAgent.toLowerCase();if(/iphone|ipad|ipod/.test(ua))return"ios";if(/android/.test(ua))return"android";return"desktop"}
function shouldShowInstallPrompt(){
  var isStandalone=window.matchMedia("(display-mode: standalone)").matches||window.navigator.standalone===true;
  if(isStandalone){localStorage.setItem("lineup_pwa_installed","true");return false;}
  var isMobile=/iphone|ipad|ipod|android/i.test(navigator.userAgent);
  if(!isMobile)return false;
  if(localStorage.getItem("lineup_install_prompt_completed")==="true")return false;
  if(localStorage.getItem("lineup_pwa_installed")==="true")return false;
  var dismissedAt=Number(localStorage.getItem("lineup_install_prompt_dismissed_at")||0);
  if(dismissedAt&&Date.now()-dismissedAt<7*24*60*60*1000)return false;
  return true;
}
function showInstallPrompt(){
  var primaryBtn=document.getElementById("installPrimary"),steps=document.getElementById("installSteps"),footer=document.querySelector(".install-footer"),platform=installPlatform();
  if(deferredPrompt){primaryBtn.textContent="Add to Home Screen";document.querySelector(".install-secondary").textContent="Not now";steps.style.display="none";}
  else{primaryBtn.textContent=platform==="ios"?"I’ll add it after":"Continue to LineUp";document.querySelector(".install-secondary").textContent="Remind me later";steps.style.display="";}
  footer.textContent=platform==="ios"?"Safari requires the Share button for Home Screen install.":"Add LineUp to your home screen for faster access.";
  document.getElementById("installPrompt").classList.add("open");
  document.getElementById("app").classList.add("install-open");
}
function hideInstallPrompt(){
  document.getElementById("installPrompt").classList.remove("open");
  document.getElementById("app").classList.remove("install-open");
}
function handleInstallPrimary(){
  if(deferredPrompt){
    var p=deferredPrompt;deferredPrompt=null;
    p.prompt();
    p.userChoice.then(function(choice){
      localStorage.setItem(choice.outcome==="accepted"?"lineup_install_prompt_completed":"lineup_install_prompt_dismissed_at",choice.outcome==="accepted"?"true":Date.now().toString());
      hideInstallPrompt();
    });
    return;
  }
  localStorage.setItem("lineup_install_prompt_dismissed_at",Date.now().toString());
  hideInstallPrompt();
}
function handleInstallSecondary(){localStorage.setItem("lineup_install_prompt_dismissed_at",Date.now().toString());hideInstallPrompt();}
