function handleLivePosition(pos,source){if(!liveLocationAllowed()||document.visibilityState==="hidden"||liveLocationSending)return;if(Date.now()-liveLocationLastSent<35000)return;liveLocationSending=true;liveLocationLastSent=Date.now();lastPosition={raw:pos,t:Date.now()};sendLocationIngest("presence",null,pos,{source:source||"live_watch"}).then(function(data){savePresenceState({enabled:true,nearest_venue_id:data.nearest_venue_id,nearest_venue_name:data.nearest_venue_name,nearest_distance_m:data.nearest_distance_m,area:data.area,updated_at:new Date().toISOString()});accountPrefs.location_pref="enabled";localStorage.setItem("lineup_account_prefs",JSON.stringify(accountPrefs));lastPresenceAt=Date.now();if(active==="profilePage")renderProfile()}).catch(function(){}).finally(function(){liveLocationSending=false})}
function startLiveLocationWatch(force){if(liveLocationWatchId!=null||!authState||!hasGeo()||document.visibilityState==="hidden")return;if(!force&&!liveLocationAllowed()){if(navigator.permissions&&navigator.permissions.query){navigator.permissions.query({name:"geolocation"}).then(function(p){if(p.state==="granted")startLiveLocationWatch(true)}).catch(function(){})}return}liveLocationWatchId=navigator.geolocation.watchPosition(function(pos){handleLivePosition(pos,"live_watch")},function(){stopLiveLocationWatch()},{enableHighAccuracy:true,timeout:12000,maximumAge:15000})}
function stopLiveLocationWatch(){if(liveLocationWatchId==null||!hasGeo())return;navigator.geolocation.clearWatch(liveLocationWatchId);liveLocationWatchId=null;liveLocationSending=false}
function checkInCurrent(){if(!current)return;if(locationBusy)return;var venueName=current.name;locationBusy=true;showToast("Verifying check-in...");getFreshPosition(0).then(function(pos){return sendLocationIngest("check_in",current.id,pos,{source:"check_in"})}).then(function(data){if(data.verified){awardReward("checkin",venueName,{checkin_id:data.checkin&&data.checkin.id});recordActivity("Verified check-in",venueName+" · +15 pts");showToast("Verified at "+venueName);loadSupabaseStatus();loadDeviceProfile();if(authState)accountRequest("claim",{favorites:favs}).catch(function(){})}else showToast("Too far away to verify")}).catch(function(){showToast("Location check failed")}).finally(function(){locationBusy=false;if(current)renderDetail()})}
function maybeCapturePresence(source){if(!authState||!hasGeo()||locationBusy)return Promise.resolve(null);if(document.visibilityState&&document.visibilityState!=="visible")return Promise.resolve(null);if(Date.now()-lastPresenceAt<3*60000)return Promise.resolve(null);if(accountPrefs.location_pref==="enabled"||presenceState)return capturePresence(source||"foreground",null,true);if(navigator.permissions&&navigator.permissions.query){return navigator.permissions.query({name:"geolocation"}).then(function(p){return p.state==="granted"?capturePresence(source||"foreground",null,true):null}).catch(function(){return null})}return Promise.resolve(null)}
document.addEventListener("visibilitychange",function(){if(document.visibilityState==="visible"){trackAppHeartbeat("app_resume");maybeCapturePresence("resume");startLiveLocationWatch()}else stopLiveLocationWatch()});
function functionRequest(name,body,headers){return fetch(SUPABASE_URL+"/functions/v1/"+name,{method:"POST",headers:headers||rewardHeaders(),body:JSON.stringify(body||{})}).then(function(res){return res.json().catch(function(){return{}}).then(function(data){if(!res.ok)throw Object.assign(new Error(data.error||name+" failed"),{status:res.status,data:data});return data})})}
function venueStatusIngest(id,note){var b=BARS.find(x=>x.id===id);if(!b)return Promise.reject(new Error("Unknown venue"));return functionRequest("venue-status-ingest",{venue_id:id,crowd_level:b.lvl,wait_minutes:b.wait||0,cover_amount:b.coverActive?b.cover:null,cover_active:!!b.coverActive,event:b.event||null,note:note||"In-app staff control",device_id:getDeviceId()},rewardHeaders())}
function syncVenueAdminToSupabase(id){if(!canAdminVenue(id))return Promise.reject(new Error("Venue role required"));venueStatusIngest(id,"In-app staff control").then(function(){loadSupabaseStatus();showToast("Venue source synced")}).catch(function(){showToast("Local update saved; sync failed")})}
function logo(b,cls){var src=ASSET_LOGOS[b.logo];return '<div class="logo '+(cls||'')+'">'+(src?'<img src="'+src+'" alt="">':'<span class="logotext">'+esc(b.logo||b.name.slice(0,2))+'</span>')+'</div>'}
function confColor(c){return c==="high"?"var(--high)":c==="medium"?"var(--medium)":"var(--low)"}function level(b){return LEVELS[b.lvl]}function isFav(id){return favs.indexOf(id)>-1}
function localConfidenceScore(b){var base=b.conf==="high"?74:b.conf==="medium"?54:30,src=(b.sources||[]).join(" ").toLowerCase(),boost=0;if(src.indexOf("owner")>-1)boost+=18;if(src.indexOf("venue")>-1||src.indexOf("staff")>-1)boost+=16;if(src.indexOf("verified")>-1||src.indexOf("check")>-1)boost+=12;if(src.indexOf("scout")>-1)boost+=10;if(src.indexOf("report")>-1)boost+=8;if(src.indexOf("app")>-1||src.indexOf("directions")>-1)boost+=5;if(src.indexOf("historical")>-1||src.indexOf("typical")>-1)boost+=3;var fresh=b.fresh==null?90:b.fresh,decay=fresh<10?8:fresh<30?3:fresh>120?-18:fresh>60?-10:0,inputs=Math.min(10,(b.confSignals||0)*2);return base+boost+decay+inputs}
function confidenceScore(b){return Math.max(0,Math.min(100,Math.round(b.confScore==null?localConfidenceScore(b):b.confScore)))}
function signalState(b){var src=(b.sources||[]).join(" ").toLowerCase(),fresh=b.fresh==null?999:b.fresh,inputs=Number(b.confSignals||0),staff=src.indexOf("owner")>-1||src.indexOf("venue")>-1||src.indexOf("staff")>-1,verified=src.indexOf("verified")>-1||src.indexOf("check")>-1||src.indexOf("nearby")>-1||src.indexOf("scout")>-1,baseline=src.indexOf("historical")>-1||src.indexOf("typical")>-1||src.indexOf("baseline")>-1;if(staff&&fresh<=90)return{key:"staff",label:"Fresh staff update",detail:freshText(b),tone:"high",mode:"Venue-confirmed read"};if(verified&&fresh<=90)return{key:"verified",label:"Verified nearby reports",detail:freshText(b),tone:"high",mode:"Location-backed read"};if(b.conf==="low"||fresh>120||inputs===0)return{key:"low",label:"Low recent data",detail:"Showing typical pattern",tone:"low",mode:"Needs fresh reports"};if(baseline||fresh>60)return{key:"typical",label:"Typical for now",detail:freshText(b),tone:"medium",mode:"Historical pattern"};return{key:"recent",label:"Recent live signals",detail:freshText(b),tone:b.conf||"medium",mode:"Crowd-sourced read"}}
function confidenceLabel(b){return signalState(b).label}
function confidenceDetail(b){return signalState(b).detail}
function confidenceTone(b){return signalState(b).tone}
function closeText(b){var now=new Date(new Date().toLocaleString("en-US",{timeZone:"America/Phoenix"})),m=now.getHours()*60+now.getMinutes(),o=b.open*60,c=b.close*60,overnight=c<=o,open=overnight?(m>=o||m<c):(m>=o&&m<c);if(!open)return "Closed · Opens "+hour(b.open);var diff=(overnight&&m>=o?c+1440-m:c-m);if(diff<=45)return "Closing soon · "+diff+"m";if(diff<=120)return "Closes in "+Math.floor(diff/60)+"h "+(diff%60)+"m";return "Closes at "+hour(b.close)}
function hour(h){var s=h>=12?"PM":"AM",n=h%12||12;return n+" "+s}
function showToast(t){var el=$("#toast");el.textContent=t;el.style.opacity=1;el.style.transform="translateX(-50%)";clearTimeout(toastTimer);toastTimer=setTimeout(function(){el.style.opacity=0;el.style.transform="translateX(-50%) translateY(20px)"},2200)}
function freshText(b){return b.fresh<1?"Updated just now":"Updated "+b.fresh+" min ago"}
function lineLeap(b){return b.lineLeap||("https://tickets.lineleap.com/search?search="+encodeURIComponent(b.name+" Tucson"))}
function liveIcon(){return '<svg class="heartbeat" viewBox="0 0 32 24" aria-hidden="true"><path class="trace" d="M2 13h6l3-8 5 16 4-10 3 2h7"/></svg>'}
function rewardState(){return{points:0,earnedSkip:false,redeemedSkips:0,reportDay:"",reportsToday:0}}
function recordActivity(title,detail){activityLog.unshift({title:title,detail:detail,at:new Date().toISOString()});activityLog=activityLog.slice(0,12);localStorage.setItem("lineup_activity_log",JSON.stringify(activityLog))}
function timeAgo(value){if(!value)return"Never";var m=Math.max(0,Math.round((Date.now()-new Date(value).getTime())/60000));if(m<1)return"now";if(m<60)return m+"m ago";var h=Math.round(m/60);if(h<24)return h+"h ago";return Math.round(h/24)+"d ago"}
function awardReward(kind,label,extra){return rewardRequest("award",Object.assign({kind:kind,label:label||""},extra||{})).then(function(data){if(data.capped)return showToast(data.message||"Daily reward points are maxed");var pts=data.awarded&&data.awarded.points||0;if(kind!=="checkin")recordActivity(kind==="verified_report"?"Verified report":"Report submitted",(label||"LineUp")+" · +"+pts+" pts");showToast("+"+pts+" LineUp points")}).catch(function(){showToast("Rewards need a secure connection")})}
function redeemSkip(){return rewardRequest("redeem").then(function(data){var code=data.redemption&&data.redemption.code;recordActivity("LineUp Skip redeemed",code?"Code "+code:"Reward issued");renderProfile();showToast("LineUp Skip added")}).catch(function(err){var data=err&&err.data;if(data&&data.summary){rewardSummary=data.summary;localStorage.setItem("lineup_reward_summary",JSON.stringify(rewardSummary));renderProfile();return showToast("Keep earning toward your LineUp Skip")}showToast("Rewards need a secure connection")})}
function rewardViewState(){var local=rewardState();if(rewardSummary)return{points:Number(rewardSummary.balance||0),redeemed:Number(rewardSummary.redeemed_skips||0),goal:Number(rewardSummary.reward_goal||REWARD_GOAL),server:true,events:rewardSummary.recent_events||[],redemptions:rewardSummary.recent_redemptions||[]};return{points:local.points,redeemed:local.redeemedSkips||0,goal:REWARD_GOAL,server:false,events:[],redemptions:[]}}
function renderRewards(){var s=rewardViewState(),pct=Math.min(100,Math.round((s.points/s.goal)*100)),left=Math.max(0,s.goal-s.points),latest=s.redemptions&&s.redemptions[0],fine=s.server?"Server-backed balance · "+s.redeemed+" skips redeemed"+(latest?" · latest "+esc(latest.code):""):"Rewards require the secure LineUp ledger. Points do not redeem from local device storage.";return `<div class="sectionlabel">REWARDS</div><div class="card rewardsHero"><div class="rewardTop"><div><b>LineUp Rewards</b><p class="muted" style="margin-top:7px">Earn points for useful nightlife signals. A free LineUp Skip should take real participation, not one night of taps.</p></div><div class="points">${s.points}</div></div><div class="rewardProgress" aria-label="${pct}% to LineUp Skip"><div style="width:${pct}%"></div></div><div class="row"><span class="muted">${left?left+" pts until free LineUp Skip":"Ready to redeem"}</span><b>${pct}%</b></div><button class="submit" onclick="redeemSkip()">${s.points>=s.goal?"Redeem LineUp Skip":"LineUp Skip locked"}</button><div class="rewardFine">${fine}</div></div><div class="card"><b>How to earn</b><div class="rewardRules"><div class="rewardRule"><b>Fresh crowd or line report</b><span>10 pts</span></div><div class="rewardRule"><b>Verified nearby report</b><span>15 pts</span></div><div class="rewardRule"><b>Verified check-in</b><span>15 pts</span></div><div class="rewardRule"><b>Approved venue insight</b><span>20 pts</span></div><div class="rewardRule"><b>Bring a friend onto LineUp</b><span>25 pts</span></div><div class="rewardRule"><b>Useful weekly streak</b><span>30 pts</span></div></div><p class="rewardFine">Anti-spam rules now live on the backend: report points cap at 3 per night, check-ins cap at 3 per night, and redemptions spend from the server ledger.</p></div>`}
function trustLabel(tier){return tier==="trusted"?"Trusted Reporter":tier==="normal"?"Building Trust":tier==="flagged"?"Needs Review":tier==="venue_staff"?"Venue Staff":tier==="owner"?"Owner":"New Reporter"}
function profileStats(){var p=profileSummary||{},score=Math.round(Number(p.reliability_score||0.5)*100);return{score:score,tier:p.trust_tier||"new",reports:Number(p.report_count||0),verified:Number(p.verified_report_count||0),checkins:Number(p.checkin_count||0),agree:Number(p.agreement_count||0),disagree:Number(p.disagreement_count||0),presence:Number(p.presence_count||0),lastReport:p.last_report_at,lastCheckin:p.last_checkin_at,lastPresence:p.last_presence_at}}
function renderProfileQuality(){var p=profileStats();return `<div class="sectionlabel">SIGNAL PROFILE</div><div class="card"><b>Your signal quality</b><div class="trustBadge">${trustLabel(p.tier)} · ${p.score}%</div><p class="muted intelCopy">LineUp weighs verified reports and check-ins more heavily over time. Reports that agree with later staff, scout, and nearby signals increase trust; conflicting reports reduce it.</p><div class="profileGrid"><div class="profileStat"><b>${p.reports}</b><span>Total reports</span></div><div class="profileStat"><b>${p.verified}</b><span>Verified reports</span></div><div class="profileStat"><b>${p.checkins}</b><span>Check-ins</span></div><div class="profileStat"><b>${p.agree}</b><span>Agreements</span></div><div class="profileStat"><b>${p.disagree}</b><span>Conflicts</span></div><div class="profileStat"><b>${p.presence}</b><span>Presence reads</span></div></div><div class="rewardFine">Last report: ${timeAgo(p.lastReport)} · Last check-in: ${timeAgo(p.lastCheckin)}</div></div>`}
function renderActivityHistory(){var rows=activityLog.length?activityLog.map(a=>`<div class="activityItem"><div><b>${esc(a.title)}</b><span>${esc(a.detail)}</span></div><span>${timeAgo(a.at)}</span></div>`).join(""):'<div class="activityItem"><div><b>No activity yet</b><span>Reports and check-ins will show here.</span></div><span>Start tonight</span></div>';return `<div class="card"><b>Recent activity</b><div class="activityList">${rows}</div></div>`}
function accountLabel(){return authState?authState.isAnonymous?"LineUp account":"Signed account":"Account required"}
function interactionVisibility(){return accountPrefs.interaction_visibility==="public"?"public":"anonymous"}
function syncAccountPrefs(silent){localStorage.setItem("lineup_account_prefs",JSON.stringify(accountPrefs));if(!authState)return Promise.resolve();return accountRequest("update_profile",{preferences:accountPrefs}).then(function(){if(!silent)showToast("Account settings saved")}).catch(function(){if(!silent)showToast("Settings saved on this phone")})}
function setInteractionVisibility(mode){accountPrefs.interaction_visibility=mode==="public"?"public":"anonymous";syncAccountPrefs(false);accountNeedsSetup()?renderSetupGate():renderProfile()}
function saveDisplayName(){var v=($("#displayNameField")&&$("#displayNameField").value||"").trim().slice(0,32);accountPrefs.display_name=v;syncAccountPrefs(false);renderProfile()}
