function publicName(){return interactionVisibility()==="anonymous"?"Anonymous User":(accountPrefs.display_name||"LineUp User")}
function profileAvatar(){var show=interactionVisibility()==="public"&&accountPrefs.avatar_url;return show?'<img src="'+esc(accountPrefs.avatar_url)+'" alt="">':(interactionVisibility()==="anonymous"?"A":"L")}
function prefStatus(kind){if(kind==="notification"&&"Notification" in window)return Notification.permission==="granted"?"enabled":Notification.permission==="denied"?"denied":accountPrefs.notification_pref||"unset";return accountPrefs[kind+"_pref"]||"unset"}
function handleAvatarFile(input){var file=input.files&&input.files[0];if(!file)return;if(String(file.type||"").indexOf("image/")!==0)return showToast("Choose an image file");if(file.size>250000)return showToast("Use a smaller profile image");var r=new FileReader();r.onload=function(){accountPrefs.avatar_url=String(r.result||"");localStorage.setItem("lineup_account_prefs",JSON.stringify(accountPrefs));renderProfile()};r.readAsDataURL(file)}
function requestNotifications(){if(!("Notification" in window)){accountPrefs.notification_pref="disabled";syncAccountPrefs(false);return showToast("Notifications unavailable")}return Notification.requestPermission().then(function(p){accountPrefs.notification_pref=p==="granted"?"enabled":p==="denied"?"denied":"unset";syncAccountPrefs(false);renderProfile();showToast(p==="granted"?"Notifications enabled":"Notifications not enabled")})}
function requestSetupLocation(){return capturePresence("setup",null,false).then(function(data){accountPrefs.location_pref=data?"enabled":"denied";return syncAccountPrefs(true)}).then(function(){renderProfile()})}
function saveSetup(){var name=($("#setupName")&&$("#setupName").value||"").trim().slice(0,32);if(!name)return showToast("Add a display name");accountPrefs.display_name=name;accountPrefs.profile_setup_completed=true;accountPrefs.terms_accepted=true;accountPrefs.data_policy_seen=true;localStorage.setItem("lineup_account_prefs",JSON.stringify(accountPrefs));return accountRequest("claim",{favorites:favs,preferences:accountPrefs}).then(function(){profileView="home";renderAll();showToast("Account ready")}).catch(function(){showToast("Could not save setup")})}
function renderAccountGate(){var root=$("#livePage");$all(".page").forEach(p=>p.classList.toggle("active",p.id==="livePage"));$all(".navbtn").forEach(n=>n.classList.remove("on"));document.body.dataset.page="accountGate";root.innerHTML=`<section class="accountGate"><div class="gateMark"><img src="/icons/icon-192.png" alt="" aria-hidden="true"></div><h1>Join LineUp</h1><p>LineUp is account-based so reports, rewards, favorites, and moderation can scale across campuses. You can still appear anonymous publicly.</p><button class="secondaryBtn appleBtn" onclick="showToast('Sign in with Apple will be added for the native app')">Continue with Apple</button><label class="fieldLabel">Email</label><input class="field" id="authEmail" type="email" autocomplete="email" placeholder="you@email.com"><label class="fieldLabel">Password</label><input class="field" id="authPassword" type="password" autocomplete="current-password" placeholder="6+ characters"><label class="fieldLabel">Display name for new accounts</label><input class="field" id="authName" maxlength="32" placeholder="Display name"><div class="sheetActions"><button class="secondaryBtn" onclick="submitEmailAuth('signin')">Sign In</button><button class="submit" onclick="submitEmailAuth('signup')">Create Account</button></div><p class="rewardFine">By continuing, you agree to LineUp’s <button class="linkBtn" onclick="showLegalSheet('privacy')">Privacy</button> and <button class="linkBtn" onclick="showLegalSheet('terms')">Terms</button>. SMS login is intentionally not used.</p></section>`}
function renderSetupGate(){var root=$("#livePage"),mode=interactionVisibility();$all(".page").forEach(p=>p.classList.toggle("active",p.id==="livePage"));$all(".navbtn").forEach(n=>n.classList.remove("on"));document.body.dataset.page="setupGate";root.innerHTML=`<section class="accountGate setupGate"><div class="profileMark setupAvatar">${profileAvatar()}</div><h1>Set Up LineUp</h1><p>Keep it fast: choose how you appear, pick favorites, and enable the permissions that make live reads smarter.</p><label class="fieldLabel">Profile photo</label><input class="field" type="file" accept="image/*" onchange="handleAvatarFile(this)"><label class="fieldLabel">Display name</label><input class="field" id="setupName" maxlength="32" value="${esc(accountPrefs.display_name||"")}" placeholder="Display name"><label class="fieldLabel">Public mode</label><div class="identityToggle"><button class="${mode==="anonymous"?"on":""}" onclick="setInteractionVisibility('anonymous')">Anonymous</button><button class="${mode==="public"?"on":""}" onclick="setInteractionVisibility('public')">Public</button></div><p class="rewardFine">Anonymous Mode shows public posts and reports as “Anonymous User.” LineUp still links activity to your account for moderation and safety.</p><div class="sectionlabel">Favorite bars</div><div class="favSetup">${activeBars().slice(0,10).map(b=>`<button class="${isFav(b.id)?"on":""}" onclick="toggleFav('${b.id}')">${esc(b.name)}</button>`).join("")}</div><div class="sheetActions"><button class="secondaryBtn" onclick="requestNotifications()">Notifications</button><button class="secondaryBtn" onclick="requestSetupLocation()">Location</button></div><button class="submit" onclick="saveSetup()">Finish Setup</button><p class="rewardFine">Permissions are optional and can be changed later in Preferences.</p></section>`}
function activeBars(){return BARS.filter(b=>b.status==="active"&&!b.deprecated)}
function barsInArea(){return activeBars().filter(b=>b.area===area)}
