function coverLabel(b){return b.coverActive&&b.cover&&b.cover!=="$0"?b.cover:""}
function sortedByCrowd(list){return [...list].sort((a,b)=>LEVELS[b.lvl].pct-LEVELS[a.lvl].pct||b.wait-a.wait)}
function openMaps(b){trackAppEvent(b.id,"directions_tap",{area:b.area});window.open("https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(b.mapQuery||b.name+" "+b.address),"_blank","noopener")}
function renderBar(b){var l=level(b),cc=closeText(b),fav=isFav(b.id),sig=signalState(b);return '<article class="barcard" data-id="'+b.id+'"><div class="cardtop">'+logo(b)+'<div class="grow"><div class="name">'+esc(b.name)+'</div><div class="tag">'+esc(b.tag)+'</div><div class="close '+(cc.indexOf("Closing")===0?"closing":cc.indexOf("Closed")===0?"closed":"")+'">'+esc(cc)+'</div></div><button class="fav '+(fav?"on":"")+'" data-fav="'+b.id+'">'+(fav?SVG.starFull:SVG.starEmpty)+'</button></div><div class="statgrid"><div><div class="bigstat" style="color:'+COLORS[b.lvl]+'">'+l.label+'</div><span class="smallcap">'+esc(b.momentum.replace("_"," "))+'</span></div><div class="right"><div class="bigstat">'+(b.wait?b.wait+" min":"No line")+'</div><span class="smallcap">est. line</span></div></div><div class="range"><em>Likely</em> '+l.range+'</div><div class="energy"><div style="width:'+l.pct+'%;background:'+COLORS[b.lvl]+';color:'+COLORS[b.lvl]+'"></div></div><div class="conf"><span class="dot" style="background:'+confColor(sig.tone)+';color:'+confColor(sig.tone)+'"></span>'+esc(sig.label)+' <span class="updated">'+esc(sig.detail)+'</span></div></article>'}
function cap(s){return s.charAt(0).toUpperCase()+s.slice(1)}
function areaPulseCopy(list){var packed=list.filter(b=>b.lvl==="packed").length,busy=list.filter(b=>b.lvl==="busy").length,active=busy+packed,favCount=list.filter(b=>isFav(b.id)).length,lead=list.find(b=>b.lvl==="packed")||list.find(b=>b.lvl==="busy"),suffix=favCount?favCount+" favorites pinned first":"Pulse can plan the move";if((packed>=1&&active>=2)||active>=3)return{title:areaName(area)+" is heating up",meta:busy+" busy · "+packed+" packed · "+suffix};if(lead)return{title:lead.name+" is picking up",meta:areaName(area)+" has "+active+" active spot"+(active===1?"":"s")+" · "+suffix};return{title:areaName(area)+" is calm right now",meta:"No busy venues yet · "+suffix}}
function renderLive(){var list=barsInArea().sort((a,b)=>(isFav(b.id)-isFav(a.id))||a.name.localeCompare(b.name)),pulse=areaPulseCopy(list);$("#tabU").className=area==="main_gate"?"on":"";$("#tabP").className=area==="fourth_downtown"?"on":"";$("#livePage").innerHTML=`<div class="pulsecard" onclick="setPage('highlightsPage')"><div class="pulseicon">${SVG.pulseTrend}</div><div><b>${esc(pulse.title)}</b><span>${esc(pulse.meta)}</span></div><div class="chev"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><polyline points="9 18 15 12 9 6"/></svg></div></div><div class="sectionlabel">LIVE BAR STATUS</div>`+list.map(renderBar).join("");bindCards()}
function bindCards(){$all(".barcard,.rankItem").forEach(c=>c.onclick=function(){openDetail(c.dataset.id)});$all(".fav").forEach(b=>b.onclick=function(e){e.stopPropagation();toggleFav(b.dataset.fav)})}
function toggleFav(id){var i=favs.indexOf(id),on=i<0;if(i>=0){favs.splice(i,1);trackAppEvent(id,"favorite_remove");showToast("Removed from favorites")}else{favs.unshift(id);trackAppEvent(id,"favorite_add");showToast("Added to favorites")}saveFavs();renderAll();if(authState)accountRequest("set_favorite",{venue_id:id,favorited:on}).catch(function(){})}
function setPage(id){if(id==="statsPage"&&!canUseVenueControls())id="livePage";active=id;window.scrollTo({top:0,behavior:"auto"});$all(".page").forEach(p=>p.classList.toggle("active",p.id===id));$all(".navbtn").forEach(n=>n.classList.toggle("on",n.dataset.page===id));renderAll()}
function renderFavs(){setPage("livePage")}
function mapPoint(c){var minLat=32.2205,maxLat=32.2370,minLng=-110.9710,maxLng=-110.9440;return{x:9+((c.lng-minLng)/(maxLng-minLng))*82,y:10+((maxLat-c.lat)/(maxLat-minLat))*78}}
function renderFallbackMap(){var mg=mapPoint({lat:USER_COORDS[1],lng:USER_COORDS[0]}),roads='<div class="maproad" style="left:24%;top:26%">University Blvd</div><div class="maproad" style="left:70%;top:15%">Speedway Blvd</div><div class="maproad" style="left:29%;top:52%;transform:rotate(-72deg)">4th Ave</div><div class="maproad" style="left:24%;top:74%">Congress St</div>',pins=activeBars().map((b)=>{var p=mapPoint(b.coords),short=b.name.replace(" Bar & Grill","").replace(" Bar + Food","").split(" ")[0];return `<button class="pin" aria-label="${esc(b.name)}" onclick="trackAppEvent('${b.id}','map_pin_tap',{map:'fallback'});openDetail('${b.id}')" style="left:${p.x}%;top:${p.y}%;background:${COLORS[b.lvl]}"><span></span></button><div class="maplabel" style="left:${p.x+3}%;top:${p.y+5}%">${esc(short)}</div>`}).join("");$("#mapBox").innerHTML='<div class="mapcanvas" id="mapCanvas">'+roads+'<div class="geofence" style="left:'+mg.x+'%;top:'+mg.y+'%"></div>'+pins+'</div><div class="maphint">Map temporarily unavailable · showing saved venue pins</div>';bindMap()}
function renderMap(){if(mapInstance){mapInstance.remove();mapInstance=null}mapMarkers=[];$("#mapPage").innerHTML='<div class="sectionlabel">LIVE MAP</div><div class="mapbox real" id="mapBox"><div class="mapSetup"><div class="mapSetupCard"><b>Loading real map</b><p class="muted">LineUp is preparing Tucson venue pins.</p></div></div></div><div class="card" style="margin-top:14px"><b>Map accuracy</b><p class="muted intelCopy">Pins use stored venue coordinates. Directions open the user’s preferred maps app.</p></div>';if(!MAPBOX_TOKEN){renderFallbackMap();$("#mapBox").insertAdjacentHTML("afterend",'<div class="card" style="margin-top:14px"><b>Live map unavailable</b><p class="muted intelCopy">Saved venue pins are still available. Directions continue to open from each venue page.</p></div>');return}loadMapbox().then(initRealMap).catch(function(){renderFallbackMap();showToast("Mapbox failed to load")})}
function loadMapbox(){if(mapboxReady)return mapboxReady;mapboxReady=import("mapbox-gl").then(function(mod){mapboxgl=mod.default||mod;return mapboxgl});return mapboxReady}
function circlePolygon(center,radiusMeters,points){var coords=[],lat=center[1],lng=center[0],earth=6371008.8,dist=radiusMeters/earth,latRad=lat*Math.PI/180,lngRad=lng*Math.PI/180;for(var i=0;i<=points;i++){var brng=i*2*Math.PI/points,lat2=Math.asin(Math.sin(latRad)*Math.cos(dist)+Math.cos(latRad)*Math.sin(dist)*Math.cos(brng)),lng2=lngRad+Math.atan2(Math.sin(brng)*Math.sin(dist)*Math.cos(latRad),Math.cos(dist)-Math.sin(latRad)*Math.sin(lat2));coords.push([lng2*180/Math.PI,lat2*180/Math.PI])}return{type:"Feature",geometry:{type:"Polygon",coordinates:[coords]}}}
function initRealMap(){var box=$("#mapBox");if(!box)return;box.innerHTML="";mapboxgl.accessToken=MAPBOX_TOKEN;mapInstance=new mapboxgl.Map({container:"mapBox",style:"mapbox://styles/mapbox/dark-v11",center:MAP_CENTER,zoom:13.6,pitch:28,bearing:-10,attributionControl:true});mapInstance.addControl(new mapboxgl.NavigationControl({showCompass:false}),"top-right");mapInstance.on("load",function(){mapInstance.addSource("user-geofence",{type:"geojson",data:circlePolygon(USER_COORDS,230,64)});mapInstance.addLayer({id:"user-geofence-fill",type:"fill",source:"user-geofence",paint:{"fill-color":"#12E0C4","fill-opacity":0.12}});mapInstance.addLayer({id:"user-geofence-line",type:"line",source:"user-geofence",paint:{"line-color":"#12E0C4","line-width":2,"line-opacity":0.75}});activeBars().forEach(function(b){var el=document.createElement("button");el.className="mapMarker "+b.lvl;el.type="button";el.setAttribute("aria-label",b.name);el.onclick=function(){trackAppEvent(b.id,"map_pin_tap",{map:"mapbox"});openDetail(b.id)};var popup=new mapboxgl.Popup({offset:28,closeButton:false}).setHTML("<b>"+esc(b.name)+"</b><br><span style='color:#B8BDC8'>"+(b.wait?b.wait+" min line":"No line")+" · "+level(b).label+"</span>");var marker=new mapboxgl.Marker({element:el,anchor:"bottom"}).setLngLat([b.coords.lng,b.coords.lat]).setPopup(popup).addTo(mapInstance);mapMarkers.push(marker)});mapInstance.resize()});box.insertAdjacentHTML("beforeend",'<div class="maphint">Drag, zoom, and tap a pin for venue details</div>')}
function renderStats(){if(intelMode==="compare")intelMode="confidence";var live=activeBars(),list=sortedByCrowd(live),shortest=[...live].sort((a,b)=>a.wait-b.wait)[0],top=list[0],activeCovers=live.filter(b=>coverLabel(b)).length,body=intelMode==="tonight"?renderIntelTonight(top,shortest,activeCovers):intelMode==="timing"?renderIntelTiming():renderIntelConfidence();$("#statsPage").innerHTML=`<div class="sectionlabel">NIGHT INTEL</div><div class="seg intelTabs"><button class="${intelMode==="tonight"?"on":""}" onclick="intelMode='tonight';renderStats()">Tonight</button><button class="${intelMode==="timing"?"on":""}" onclick="intelMode='timing';renderStats()">Timing</button><button class="${intelMode==="confidence"?"on":""}" onclick="intelMode='confidence';renderStats()">Signals</button></div><div class="intelBody">${body}<div class="card intelNote"><b>Why this exists</b><p class="muted intelCopy">Intel answers timing, confidence, and value questions without making users reread the live bar list.</p></div></div>`}
function renderIntelTonight(top,shortest,activeCovers){return '<div class="card intelHero"><div class="intelTop"><b>Best live move</b><span class="muted">Right now</span></div><div class="intelMove"><div class="intelVenue"><b>'+esc(top.name)+'</b><div class="muted">'+level(top).label+' · '+top.event+'</div></div><div class="intelMetric">'+top.wait+' min</div></div></div><div class="intelGrid"><div class="intelTile"><span class="muted">Shortest line</span><div><b>'+esc(shortest.name)+'</b><small>'+(shortest.wait?shortest.wait+" min":"No line")+'</small></div></div><div class="intelTile"><span class="muted">Cover alerts</span><div><b>'+(activeCovers||"None")+'</b><small>'+(activeCovers?"Active tonight":"Hidden unless enabled")+'</small></div></div></div>'}
function renderIntelTiming(){return '<div class="card intelHero"><div class="intelTop"><b>When to move</b><span class="muted">Tonight</span></div><div class="timeGrid"><div class="timeSlot"><b>9 PM</b><span>Easy</span></div><div class="timeSlot"><b>10 PM</b><span>Rising</span></div><div class="timeSlot"><b>11 PM</b><span>Peak</span></div><div class="timeSlot"><b>12 AM</b><span>Lines</span></div></div><div class="chart">'+spark()+'</div></div><div class="intelGrid"><div class="intelTile"><span class="muted">Leave before</span><div><b>10:35 PM</b><small>Best odds of short lines</small></div></div><div class="intelTile"><span class="muted">Peak pressure</span><div><b>11 PM-12 AM</b><small>Expect cover + waits</small></div></div></div>'}
function renderIntelConfidence(){var live=activeBars(),staff=live.filter(b=>signalState(b).key==="staff").length,verified=live.filter(b=>signalState(b).key==="verified").length,typical=live.filter(b=>signalState(b).key==="typical"||signalState(b).key==="recent").length,low=live.filter(b=>signalState(b).key==="low").length;return '<div class="card intelHero"><b>Read quality</b><p class="muted intelCopy">LineUp labels each read by source quality and freshness, so users know whether they are seeing a live confirmation or a typical pattern for this time.</p><div class="signalGrid"><div class="timeSlot"><b>'+staff+'</b><span>Fresh staff</span></div><div class="timeSlot"><b>'+verified+'</b><span>Nearby reports</span></div><div class="timeSlot"><b>'+typical+'</b><span>Typical now</span></div><div class="timeSlot"><b>'+low+'</b><span>Needs reports</span></div></div></div><div class="card intelNote"><b>How reads improve</b><p class="muted intelCopy">Fresh staff updates, verified nearby reports, check-ins, app demand, and historical baselines are blended together. Older signals fade so the app can return to “Typical for now” instead of overstating stale activity.</p></div>'}
function renderStatsCompact(){var live=activeBars(),list=sortedByCrowd(live),shortest=[...live].sort((a,b)=>a.wait-b.wait)[0],top=list[0],fresh=Math.min.apply(null,live.map(b=>b.fresh)),bestSig=signalState(top);return '<div class="intelGrid"><div class="intelTile"><span class="muted">Best move</span><div><b>'+esc(top.name)+'</b><small>'+top.wait+' min · '+level(top).label+'</small></div></div><div class="intelTile"><span class="muted">Shortest line</span><div><b>'+esc(shortest.name)+'</b><small>'+(shortest.wait?shortest.wait+" min":"No line")+'</small></div></div><div class="intelTile"><span class="muted">Freshest read</span><div><b>'+fresh+' min</b><small>Latest venue signal</small></div></div><div class="intelTile"><span class="muted">Read quality</span><div><b>'+esc(bestSig.label)+'</b><small>'+esc(bestSig.mode)+'</small></div></div></div>'}
function ownerRequest(){return fetch(SUPABASE_URL+"/functions/v1/owner-dashboard",{method:"POST",headers:rewardHeaders(),body:JSON.stringify({})}).then(function(res){return res.json().then(function(data){if(!res.ok)throw new Error(data.error||"Owner dashboard failed");return data})}).then(function(data){ownerData=data;return data})}
function ownerAction(action,extra){if(!isOwnerAccount())return Promise.reject(new Error("Owner account required"));return functionRequest("owner-actions",Object.assign({action:action,device_id:getDeviceId()},extra||{}),rewardHeaders())}
function ownerControlVenues(){var rows=ownerData&&ownerData.venue_activity&&ownerData.venue_activity.length?ownerData.venue_activity:activeBars();return rows.slice().sort(function(a,b){return String(a.name).localeCompare(String(b.name))})}
function ownerVenueOptions(selected){return ownerControlVenues().map(function(v){var state=v.status&&v.status!=="active"?" · "+v.status:"";return '<option value="'+esc(v.id)+'" '+(v.id===selected?"selected":"")+'>'+esc(v.name+state)+'</option>'}).join("")}
function ownerPublishVenue(){var id=$("#ownerVenue").value,b=BARS.find(v=>v.id===id),wait=parseInt($("#ownerWait").value,10),cover=$("#ownerCover").value,event=$("#ownerEvent").value.trim(),lvl=$("#ownerCrowd").value;if(!b)return;showToast("Publishing owner update...");ownerAction("venue_live_update",{venue_id:id,crowd_level:lvl,wait_minutes:isNaN(wait)?0:wait,cover_amount:cover||null,cover_active:!!cover,event:event||null,note:"Owner control update"}).then(function(){saveBarUpdate(b,{lvl:lvl,wait:isNaN(wait)?0:wait,coverActive:!!cover,cover:cover||b.cover,event:event||b.event,fresh:0,conf:"high",sources:["Owner override","Supabase live signal","Fresh manual update"]});return ownerRequest()}).then(function(){loadSupabaseStatus();renderOwnerDashboard();showToast("Owner update live")}).catch(function(err){showToast(err.message||"Owner update failed")})}
function ownerSetVenueStatus(status){var id=$("#ownerVenue").value,b=BARS.find(v=>v.id===id)||(ownerControlVenues().find(v=>v.id===id));if(!b)return;if(status==="hidden"&&!confirm("Hide "+b.name+" from public nightlife lists? You can reactivate it here later."))return;showToast("Updating venue status...");ownerAction("set_venue_status",{venue_id:id,status:status,deprecated:false}).then(function(){var local=BARS.find(v=>v.id===id);if(local){local.status=status;local.deprecated=false}return ownerRequest()}).then(function(){loadSupabaseStatus();renderOwnerDashboard();showToast(status==="active"?"Venue reactivated":"Venue hidden")}).catch(function(err){showToast(err.message||"Status update failed")})}
function ownerSetRedemption(id,status){showToast("Updating redemption...");ownerAction("redemption_status",{redemption_id:id,status:status}).then(function(){return ownerRequest()}).then(function(){renderOwnerDashboard();showToast("Redemption updated")}).catch(function(err){showToast(err.message||"Redemption update failed")})}
function ownerOpenVenue(id){var b=BARS.find(v=>v.id===id);$("#reportSheet").classList.add("open");$("#sheetcard").innerHTML='<span class="accessPill">OWNER DETAIL</span><h2>'+esc(b?b.name:"Venue")+'</h2><p class="sheetIntro">Loading recent signals, check-ins, reports, and audit history.</p>';ownerAction("venue_detail",{venue_id:id}).then(renderOwnerVenueDetail).catch(function(err){$("#sheetcard").innerHTML='<span class="accessPill">OWNER DETAIL</span><h2>Could not load venue</h2><p class="sheetIntro">'+esc(err.message||"Owner detail failed")+'</p><button class="submit" onclick="closeSheet()">Close</button>'})}
function ownerCompactRow(title,meta,right){return '<div class="ownerVenueRow"><div><b>'+esc(title)+'</b><span>'+esc(meta)+'</span></div><b>'+esc(right||"")+'</b></div>'}
function renderOwnerVenueDetail(data){var v=data.venue||{},l=data.live_status||{},reports=data.reports||[],checkins=data.checkins||[],events=data.events||[],signals=data.signals||[],audits=data.audits||[];$("#sheetcard").innerHTML=`<span class="accessPill">OWNER DETAIL</span><h2>${esc(v.name||v.id)}</h2><p class="sheetIntro">${esc(v.address||"")} ${l.crowd_level?("Current read: "+esc(l.crowd_level)+" · "+(l.wait_minutes||0)+" min line"):""}</p><div class="sectionlabel">RECENT SIGNALS</div><div class="ownerVenueRows">${signals.slice(0,5).map(s=>ownerCompactRow(s.signal_label||s.source_type,(s.crowd_level||"")+" · "+(s.wait_minutes||0)+" min · "+timeAgo(s.created_at),s.reliability?Math.round(Number(s.reliability)*100)+"%":"")).join("")||ownerCompactRow("No recent signals","Waiting for staff, reports, or app activity","")}</div><div class="sectionlabel">REPORTS + CHECK-INS</div><div class="ownerVenueRows">${reports.slice(0,4).map(r=>ownerCompactRow("Report: "+(r.crowd_level||"unknown"),(r.location_verified?"Verified":"Unverified")+" · "+(r.wait_minutes||0)+" min · "+timeAgo(r.created_at),r.source||"")).join("")}${checkins.slice(0,4).map(c=>ownerCompactRow("Check-in",(c.verified?"Verified":"Unverified")+" · "+Math.round(Number(c.distance_m||0))+"m · "+timeAgo(c.created_at),"")).join("")||""}</div><div class="sectionlabel">APP ACTIVITY</div><div class="ownerVenueRows">${events.slice(0,6).map(e=>ownerCompactRow(e.event_type,timeAgo(e.created_at),"")).join("")||ownerCompactRow("No app events","No recent taps for this venue","")}</div><div class="sectionlabel">OWNER AUDIT</div><div class="ownerVenueRows">${audits.slice(0,5).map(a=>ownerCompactRow(a.action,a.target_type+" · "+timeAgo(a.created_at),"")).join("")||ownerCompactRow("No owner actions","Nothing logged yet","")}</div><div class="sheetActions"><button class="secondaryBtn" onclick="closeSheet()">Close</button><button class="submit" onclick="closeSheet();setPage('statsPage')">Owner Control</button></div>`}
function refreshOwnerDashboard(){if(!isOwnerAccount())return showToast("Owner account required");showToast("Refreshing owner data...");ownerRequest().then(function(){renderOwnerDashboard();showToast("Owner data refreshed")}).catch(function(){ownerData=null;showToast("Owner access denied")})}
function refreshOwnerDashboardSilent(){if(active!=="statsPage"||!isOwnerAccount()||document.visibilityState==="hidden")return;ownerRequest().then(function(){if(active==="statsPage"&&isOwnerAccount())renderOwnerDashboard()}).catch(function(){})}
function exitOwnerMode(){ownerData=null;if(ownerMap){ownerMap.remove();ownerMap=null}setPage("profilePage");showToast("Owner tools closed")}
function ownerMetric(label,value){return '<div class="ownerMetric"><b>'+esc(value)+'</b><span>'+esc(label)+'</span></div>'}
function ownerMix(title,mix){var keys=Object.keys(mix||{});return '<div class="card"><b>'+esc(title)+'</b><div class="ownerMix">'+(keys.length?keys.map(k=>'<span class="ownerPill">'+esc(k)+' <strong>'+mix[k]+'</strong></span>').join(""):'<span class="ownerPill">No activity yet</span>')+'</div></div>'}
function ownerSection(title,right,body){return '<div class="sectionlabel">'+esc(title)+'</div><div class="card"><div class="ownerPanelTitle"><b>'+esc(title)+'</b><span>'+esc(right||"")+'</span></div>'+body+'</div>'}
function ownerVenueRows(venues){return venues.length?venues.map(v=>'<button class="ownerVenueRow" onclick="ownerOpenVenue(&quot;'+esc(v.id)+'&quot;)"><div><b>'+esc(v.name)+'</b><span>'+esc(v.status||"active")+' · '+esc(v.crowd_level)+' · '+(v.wait_minutes==null?"No line":v.wait_minutes+" min")+' · '+v.reports_24h+' reports · '+v.checkins_24h+' check-ins · '+v.app_events_24h+' app events</span></div><b>'+v.active_users_60m+'</b></button>').join(""):'<div class="ownerVenueRow"><div><b>No venue activity yet</b><span>Live activity will appear as users open the app.</span></div><b>0</b></div>'}
function ownerSessionRows(rows){return rows&&rows.length?rows.slice(0,24).map(function(s){var label=s.has_location?"Mapped user":"Active user",detail=esc(s.event_type||s.source||"active")+" · "+esc(s.venue_name||"No venue yet")+" · "+(s.age_min||0)+" min ago · "+(s.has_location?"location":"no location yet"),badge=s.location_verified?"verified":s.has_location?"mapped":"live";return '<div class="ownerVenueRow"><div><b>'+esc(label)+'</b><span>'+detail+'</span></div><b>'+esc(badge)+'</b></div>'}).join(""):'<div class="ownerVenueRow"><div><b>No active sessions yet</b><span>Signed-in users appear here when the app is open or recently resumed.</span></div><b>0</b></div>'}
function ownerRedemptionRows(reds){return reds.length?reds.map(r=>'<div class="ownerVenueRow ownerCodeRow"><div><b>'+esc((r.reward_type||"reward").replace(/_/g," "))+'</b><span>'+esc(r.status)+' · '+(r.points_spent||0)+' pts · '+esc(r.code||"no code")+' · '+timeAgo(r.created_at)+'</span></div><div class="ownerCodeActions"><button class="hot" onclick="ownerSetRedemption(&quot;'+esc(r.id)+'&quot;,&quot;redeemed&quot;)">Redeem</button><button onclick="ownerSetRedemption(&quot;'+esc(r.id)+'&quot;,&quot;cancelled&quot;)">Cancel</button></div></div>').join(""):'<div class="ownerVenueRow"><div><b>No reward redemptions yet</b><span>LineUp Skip redemptions will appear here for owner handling.</span></div><b></b></div>'}
function ownerAuditRows(audits){return audits.length?audits.slice(0,10).map(a=>ownerCompactRow(a.action,a.target_type+' · '+(a.target_id||'system')+' · '+timeAgo(a.created_at),"")).join(""):'<div class="ownerVenueRow"><div><b>No owner actions logged yet</b><span>Owner and staff security activity will appear here.</span></div><b></b></div>'}
function ownerSetControlVenue(id){var v=(ownerData&&ownerData.venue_activity||[]).find(x=>x.id===id)||BARS.find(b=>b.id===id);if(!v)return;if($("#ownerCrowd"))$("#ownerCrowd").value=LEVELS[v.crowd_level]?v.crowd_level:(v.lvl||"slow");if($("#ownerWait"))$("#ownerWait").value=v.wait_minutes==null?(v.wait||0):v.wait_minutes;if($("#ownerEvent"))$("#ownerEvent").value=v.event||""}
function renderOwnerDashboard(){var d=ownerData;if(!d){$("#statsPage").innerHTML='<div class="sectionlabel">OWNER MODE</div><div class="card"><b>Loading owner dashboard</b><p class="muted intelCopy">Pulling private operating stats from Supabase.</p></div>';refreshOwnerDashboard();return}var s=d.summary||{},venues=(d.venue_activity||[]).slice(0,12),generated=s.generated_at?timeAgo(s.generated_at):"now",first=ownerControlVenues()[0]&&ownerControlVenues()[0].id||activeBars()[0]&&activeBars()[0].id,reds=d.recent_redemptions||[],audits=d.audit_logs||[];$("#statsPage").innerHTML=`<div class="ownerHeader"><div><div class="sectionlabel">OWNER MODE</div><h2>LineUp Control</h2></div><button class="iconbtn" onclick="refreshOwnerDashboard()" aria-label="Refresh owner data"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><path d="M21 12a9 9 0 0 1-15.3 6.4"/><path d="M3 12A9 9 0 0 1 18.3 5.6"/><path d="M18 2v4h-4"/><path d="M6 22v-4h4"/></svg></button></div><div class="ownerGrid">${ownerMetric("Active users · 15 min",s.active_users_15m||0)}${ownerMetric("Active users · 60 min",s.active_users_60m||0)}${ownerMetric("Mapped users · 15 min",s.active_locations_15m||0)}${ownerMetric("No location · 60 min",s.active_without_location_60m||0)}${ownerMetric("Reports · 24h",(s.verified_reports_24h||0)+"/"+(s.reports_24h||0)+" verified")}${ownerMetric("Check-ins · 24h",(s.verified_checkins_24h||0)+"/"+(s.checkins_24h||0)+" verified")}${ownerMetric("Redemptions · 24h",s.redemptions_24h||0)}</div><div class="ownerQuickGrid"><button class="hot" onclick="refreshOwnerDashboard()">Refresh Data</button><button onclick="ownerOpenVenue($('#ownerVenue')?$('#ownerVenue').value:'${esc(first)}')">Venue Detail</button><button onclick="refreshOwnerDashboard()">Sync Now</button></div><div class="sectionlabel">ACTIVE USER MAP</div><div class="ownerMap" id="ownerMap"><div class="mapSetup"><div class="mapSetupCard"><b>Loading active map</b><p class="muted">Showing live foreground location dots when users have granted location.</p></div></div></div><div class="card ownerNotice"><div class="row"><div><b>Owner operating data</b><p class="muted intelCopy">Owner mode shows live app sessions, venue interactions, and precise foreground location snapshots when a signed-in user has granted location. Users without a current location still appear in the session list so active traffic is visible.</p></div></div><div class="rewardFine">Generated ${generated}. Owner access is controlled by authenticated account role.</div></div><div class="sectionlabel">LIVE USER SESSIONS</div><div class="ownerVenueRows">${ownerSessionRows(d.active_sessions||[])}</div>${ownerSection("Live Controls","Owner-only",`<label class="fieldLabel">Venue</label><select class="field" id="ownerVenue" onchange="ownerSetControlVenue(this.value)">${ownerVenueOptions(first)}</select><label class="fieldLabel">Live read</label><div class="adminMini"><select class="field" id="ownerCrowd">${Object.keys(LEVELS).map(k=>'<option value="'+k+'">'+LEVELS[k].label+'</option>').join("")}</select><input class="field" id="ownerWait" type="number" min="0" max="180" value="0" placeholder="Wait min"></div><label class="fieldLabel">Cover + event</label><div class="adminMini"><select class="field" id="ownerCover"><option value="">No cover</option><option value="$5">$5</option><option value="$10">$10</option><option value="$15">$15</option><option value="$20">$20</option></select><input class="field" id="ownerEvent" placeholder="Event note"></div><div class="sheetActions"><button class="submit" onclick="ownerPublishVenue()">Publish Update</button><button class="secondaryBtn" onclick="ownerSetVenueStatus('hidden')">Hide Venue</button></div><div class="sheetActions" style="margin-top:8px"><button class="secondaryBtn" onclick="ownerSetVenueStatus('active')">Reactivate</button><button class="secondaryBtn" onclick="ownerOpenVenue($('#ownerVenue').value)">Venue Detail</button></div>`)}${ownerSection("Staff Access","Account roles",`<p class="muted intelCopy">Staff codes are retired. Venue staff access now comes from Supabase account roles tied to a specific venue, so regular users never see venue controls and staff cannot update other bars.</p><div class="lockNote">Assign or remove staff roles in the backend before public launch. No shared passwords are accepted by the app.</div>`)}<div class="sectionlabel">VENUE ACTIVITY</div><div class="ownerVenueRows">${ownerVenueRows(venues)}</div>${ownerSection("Reward Redemptions","LineUp Skip",`<div class="ownerVenueRows">${ownerRedemptionRows(reds)}</div>`)}${ownerMix("App event mix",d.event_mix)}${ownerMix("Reward mix",d.reward_mix)}<div class="sectionlabel">OWNER AUDIT</div><div class="ownerVenueRows">${ownerAuditRows(audits)}</div>`;ownerSetControlVenue(first);initOwnerMap()}
function initOwnerMap(){var box=$("#ownerMap"),d=ownerData;if(!box||!d)return;if(ownerMap){ownerMap.remove();ownerMap=null}if(!MAPBOX_TOKEN){box.innerHTML='<div class="mapSetup"><div class="mapSetupCard"><b>Owner map unavailable</b><p class="muted">Mapbox token is required for active-user map tiles.</p></div></div>';return}loadMapbox().then(function(){box.innerHTML="";mapboxgl.accessToken=MAPBOX_TOKEN;ownerMap=new mapboxgl.Map({container:"ownerMap",style:"mapbox://styles/mapbox/dark-v11",center:MAP_CENTER,zoom:13.4,pitch:20,attributionControl:false});ownerMap.addControl(new mapboxgl.NavigationControl({showCompass:false}),"top-right");ownerMap.on("load",function(){(d.venue_activity||[]).forEach(function(v){if(!Number.isFinite(v.lat)||!Number.isFinite(v.lng))return;var el=document.createElement("button");el.className="mapMarker "+(v.crowd_level||"slow");el.type="button";el.setAttribute("aria-label",v.name);new mapboxgl.Marker({element:el,anchor:"bottom"}).setLngLat([v.lng,v.lat]).addTo(ownerMap)});(d.active_points||[]).forEach(function(p){var el=document.createElement("div");el.className="ownerUserDot "+(p.age_min>15?"dim":"");el.title=(p.precision==="exact_foreground"?"Exact foreground":"Rounded")+" · "+p.nearest_venue_name+" · "+p.age_min+"m ago";new mapboxgl.Marker({element:el,anchor:"center"}).setLngLat([p.lng,p.lat]).addTo(ownerMap)});ownerMap.resize()})}).catch(function(){box.innerHTML='<div class="mapSetup"><div class="mapSetupCard"><b>Owner map failed</b><p class="muted">Private stats still loaded below.</p></div></div>'})}
function openProfileView(view){profileView=view||"home";active="profilePage";setPage("profilePage")}
function profileBack(){profileView="home";renderProfile()}
function profileMenu(label,view,meta){return `<button class="profileMenuItem" onclick="openProfileView('${view}')"><span><b>${label}</b><small>${meta||""}</small></span>${SVG.chevRight}</button>`}
function renderProfileHome(){var mode=interactionVisibility(),name=publicName(),status=authState&&authState.email?authState.email:"Signed account";return `<div class="profileHero accountHero"><div class="profileMark">${profileAvatar()}</div><h1>${esc(name)}</h1><p class="muted">${esc(status)} · ${mode==="anonymous"?"Publicly anonymous":"Public profile on"}</p><button class="secondaryBtn compactBtn" onclick="openProfileView('edit')">Edit Profile</button></div><div class="profileMenu">${profileMenu("Edit Profile","edit","Photo, display name, anonymous mode")}${profileMenu("Favorites","favorites",favs.length+" saved bars")}${profileMenu("Preferences","preferences","Notifications and location")}${profileMenu("LineUp Rewards","rewards",(rewardViewState().points||0)+" points")}${profileMenu("Privacy & Data","privacy","Privacy, data usage, terms")}${profileMenu("Help / Support","help","Contact and safety")}</div>${renderProfileQuality()}<button class="secondaryBtn logoutBtn" onclick="signOutAccount()">Log Out</button>`}
function renderEditProfile(){var mode=interactionVisibility();return `<button class="backBtn" onclick="profileBack()">${SVG.back} Profile</button><div class="sectionlabel">EDIT PROFILE</div><div class="card accountCard"><div class="profileMark smallAvatar">${profileAvatar()}</div><label class="fieldLabel">Profile photo</label><input class="field" type="file" accept="image/*" onchange="handleAvatarFile(this)"><label class="fieldLabel">Display name</label><div class="adminMini"><input class="field" id="displayNameField" value="${esc(accountPrefs.display_name||"")}" maxlength="32" placeholder="Display name"><button class="secondaryBtn" onclick="saveDisplayName()">Save</button></div><label class="fieldLabel">Anonymous mode</label><div class="identityToggle"><button class="${mode==="anonymous"?"on":""}" onclick="setInteractionVisibility('anonymous')">Anonymous</button><button class="${mode==="public"?"on":""}" onclick="setInteractionVisibility('public')">Public</button></div><p class="rewardFine">Anonymous Mode: When enabled, your public posts and reports show as “Anonymous User.” LineUp can still link activity to your account for moderation and safety.</p></div>`}
function renderFavoritesPage(){return `<button class="backBtn" onclick="profileBack()">${SVG.back} Profile</button><div class="sectionlabel">FAVORITES</div><div class="card"><b>Your Favorite Bars</b><p class="muted intelCopy">Favorites are saved to your account and appear first in Live.</p><div class="favSetup allFavs">${activeBars().map(b=>`<button class="${isFav(b.id)?"on":""}" onclick="toggleFav('${b.id}')">${esc(b.name)}</button>`).join("")}</div></div>`}
function renderPreferencesPage(){var pc=presenceCopy(),n=prefStatus("notification"),l=prefStatus("location");return `<button class="backBtn" onclick="profileBack()">${SVG.back} Profile</button><div class="sectionlabel">PREFERENCES</div><div class="card permission"><b>Notifications</b><p class="muted intelCopy">Get future alerts when a favorite bar gets packed, a line gets short, events go live, or rewards update.</p><div class="rewardRule"><b>Status</b><span>${esc(cap(n))}</span></div><button class="submit" onclick="requestNotifications()">Enable Notifications</button></div><div class="card permission"><b>Location</b><p class="muted intelCopy">Enable location to improve nearby bar accuracy and live crowd reports while the app is open.</p><div class="locationStatus"><b>${esc(pc.title)}</b><span>${esc(pc.detail)}</span></div><div class="rewardRule"><b>Preference</b><span>${esc(cap(l))}</span></div><button class="submit" onclick="requestSetupLocation()">${presenceState?"Refresh Location":"Enable Location"}</button></div>`}
function renderRewardsPage(){return `<button class="backBtn" onclick="profileBack()">${SVG.back} Profile</button>${renderRewards()}<details class="card photoPanel" open><summary>How to Earn <span class="muted">Open</span></summary><p class="muted intelCopy">Submit accurate crowd reports, add useful line photos, post highlights, report fake or outdated info, and use LineUp consistently.</p></details><details class="card photoPanel"><summary>What Rewards Can Be Used For <span class="muted">Open</span></summary><p class="muted intelCopy">Rewards are designed for future LineUp Skip credits, partner perks, and campus nightlife benefits once venue operations are ready.</p></details><details class="card photoPanel"><summary>Rules <span class="muted">Open</span></summary><p class="muted intelCopy">Points are server-backed, capped per night, and tied to verified account activity. Fake or spammy reports can lose trust or rewards.</p></details>`}
function legalCopy(kind){if(kind==="terms")return{title:"Terms of Service",body:"Use LineUp responsibly. Do not post fake reports, unsafe content, harassment, or venue misinformation. Rewards and venue data can be changed, revoked, or corrected when abuse or errors are found. LineUp is an informational nightlife tool, not a guarantee of entry, safety, pricing, event availability, or wait time."};return{title:"Privacy & Data",body:"LineUp collects account email, Apple login identifiers when added, display name, profile photo, favorite bars, reports, comments and photos when available, precise foreground location snapshots when location is enabled, notification preferences, device/session/auth metadata, app activity, rewards activity, and moderation metadata. Public anonymous mode changes display only; internal account IDs and operating data remain available for trust, abuse prevention, rewards, safety review, owner analytics, and live app operations."}}
function showLegalSheet(kind){var p=legalCopy(kind);$("#reportSheet").classList.add("open");$("#sheetcard").innerHTML=`<h2>${esc(p.title)}</h2><p class="sheetIntro">${esc(p.body)}</p><button class="submit" onclick="closeSheet()">Close</button>`}
function renderPrivacyPage(kind){var p=legalCopy(kind);return `<button class="backBtn" onclick="profileBack()">${SVG.back} Profile</button><div class="sectionlabel">${kind==="terms"?"TERMS":"PRIVACY & DATA"}</div><div class="card"><b>${p.title}</b><p class="muted intelCopy">${p.body}</p><div class="profileMenu">${profileMenu("Privacy Policy","privacy","What LineUp collects and why")}${profileMenu("Terms of Service","terms","Use rules and limitations")}</div></div>`}
function renderHelpPage(){return `<button class="backBtn" onclick="profileBack()">${SVG.back} Profile</button><div class="sectionlabel">HELP</div><div class="card"><b>Support</b><p class="muted intelCopy">For now, send bugs, venue corrections, safety issues, or account questions to the LineUp owner. Owner tools can investigate abuse without exposing private identity publicly.</p><button class="submit" onclick="showToast('Support channel coming soon')">Contact Support</button></div>`}
function renderProfile(){var views={home:renderProfileHome,edit:renderEditProfile,favorites:renderFavoritesPage,preferences:renderPreferencesPage,rewards:renderRewardsPage,privacy:function(){return renderPrivacyPage("privacy")},terms:function(){return renderPrivacyPage("terms")},help:renderHelpPage};$("#profilePage").innerHTML=(views[profileView]||views.home)()}
function renderHighlightsPage(){$("#highlightsPage").innerHTML='<div class="sectionlabel">PULSE PLANNER</div>'+renderHighlights("page");bindCards()}
function setPulseVibe(v){pulseVibe=v;renderHighlightsPage()}
function vibeOptions(){return[{id:"chill",name:"Chill night",desc:"Easy with friends",tags:["chill","friends","patio","pub","speakeasy"]},{id:"dance",name:"High energy",desc:"Dance, DJ, loud room",tags:["dance","lively","edm","late","drag"]},{id:"patio",name:"Patio route",desc:"Outdoor / open-air feel",tags:["patio","rooftop","tiki","friends"]},{id:"value",name:"Easy-entry move",desc:"Lower friction tonight",tags:["no_cover","food","casual","friends"]}]}
function planScore(b,tags){var scene=(b.scenes||[]).filter(s=>tags.indexOf(s)>-1).length*24,live=b.lvl==="packed"?18:b.lvl==="busy"?24:b.lvl==="slow"?16:6,line=b.wait===0?18:b.wait<=10?14:b.wait<=20?8:-8,confidence=Math.round(confidenceScore(b)/10);return scene+live+line+confidence}
function pulseReason(b){var l=level(b).label.toLowerCase(),line=b.wait?b.wait+" min line":"no line",sig=signalState(b);return cap(l)+" right now with "+line+". "+esc(b.tag)+" fits this plan. Read quality: "+sig.label.toLowerCase()+"."}
function renderHighlights(mode){var options=vibeOptions(),picked=options.find(v=>v.id===pulseVibe)||options[0],picks=activeBars().map(b=>({bar:b,score:planScore(b,picked.tags)})).sort((a,b)=>b.score-a.score).slice(0,3),intro=mode==="page"?'<div class="pulsecard"><div class="pulseicon">'+SVG.pulseTrend+'</div><div><b>Build the plan, then move.</b><span>Pick the kind of night you want. Pulse uses venue style plus live data to guide the next stop.</span></div></div>':"",intel='<details class="card photoPanel"><summary>Night Intel <span class="muted">For the curious</span></summary><div style="margin-top:12px">'+renderStatsCompact()+'</div></details>';return intro+'<div class="pulsePlan"><div class="vibeGrid">'+options.map(v=>'<button class="vibeBtn '+(pulseVibe===v.id?"on":"")+'" onclick="setPulseVibe(&quot;'+v.id+'&quot;)"><b>'+v.name+'</b><span>'+v.desc+'</span></button>').join("")+'</div><div class="sectionlabel">RECOMMENDED ROUTE</div>'+picks.map((p,i)=>'<article class="card planHero barcard" data-id="'+p.bar.id+'"><div class="planPick"><div class="planRank">'+(i+1)+'</div><div><h3>'+esc(p.bar.name)+'</h3><p class="planReason">'+pulseReason(p.bar)+'</p><div class="planMeta"><span class="planPill hot">'+(p.bar.wait?p.bar.wait+" min":"No line")+'</span><span class="planPill">'+level(p.bar).label+'</span><span class="planPill">'+areaName(p.bar.area)+'</span></div></div></div></article>').join("")+'<div class="card"><b>How Pulse thinks</b><p class="muted intelCopy">Pulse weighs the scene you selected, live crowd level, line wait, and confidence. It should feel like a friend who knows the bars and is watching the night change.</p></div>'+intel+'<div class="sectionlabel">TONIGHT’S EVENTS</div>'+activeBars().filter(b=>b.event).slice(0,4).map(b=>'<div class="card row barcard" data-id="'+b.id+'"><div><b>'+esc(b.name)+'</b><div class="muted">'+esc(b.event)+'</div></div><span class="muted">'+(b.wait?b.wait+" min":"No line")+'</span></div>').join("")+'</div>'}
function openDetail(id){current=BARS.find(b=>b.id===id);if(current){trackAppEvent(id,"detail_view",{area:current.area,page:active});loadVenueReports(id)}detailTab="live";renderDetail();var el=$("#detail");el.style.transform="";el.scrollTop=0;el.classList.add("open")}
function closeDetail(){var el=$("#detail");el.style.transform="";el.classList.remove("open")}
function navigateDetail(toId,dir){
  var el=$("#detail"),stage=el.querySelector(".detailStage"),outX=dir==="left"?"-105%":"105%",inX=dir==="left"?"105%":"-105%";
  if(!stage)return;
  stage.style.transition="transform .2s ease-in, opacity .2s ease-in";stage.style.transform="translateX("+outX+")";stage.style.opacity=".82";
  setTimeout(function(){
    current=BARS.find(b=>b.id===toId);detailTab="live";renderDetail();
    loadVenueReports(toId);
    el.scrollTop=0;stage=el.querySelector(".detailStage");stage.style.transition="none";stage.style.transform="translateX("+inX+")";stage.style.opacity=".82";
    void stage.offsetWidth;
    stage.style.transition="transform .2s ease-out, opacity .2s ease-out";stage.style.transform="translateX(0)";stage.style.opacity="1";
    setTimeout(function(){stage.style.transition="";stage.style.transform="";stage.style.opacity=""},220);
  },200);
}
function detailMiniRow(b){var cover=coverLabel(b),items=['<div class="mini"><span><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg></span><b>Hours</b><small>'+closeText(b)+'</small></div>'];if(cover)items.push('<div class="mini"><span><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg></span><b>Cover</b><small>'+cover+'</small></div>');items.push('<div class="mini"><span>'+SVG.lastcall+'</span><b>Last Call</b><small>'+b.lastCall+'</small></div>');return '<div class="minirow">'+items.join("")+'</div>'}
function renderDetail(){var b=current,l=level(b),reports=reportRows(b.id),sig=signalState(b),el=$("#detail");el.innerHTML=`<div class="detailtop"><button class="iconbtn" onclick="closeDetail()"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><path d="M15 18l-6-6 6-6"/></svg></button><div style="flex:1"></div><button class="iconbtn" onclick="trackAppEvent(current.id,'share_tap');navigator.share?navigator.share({title:'LineUp',url:location.href}):showToast('Share ready')"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><path d="M4 12v8a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg></button><button class="iconbtn fav ${isFav(b.id)?"on":""}" onclick="toggleFav('${b.id}')">${isFav(b.id)?SVG.starFull:SVG.starEmpty}</button></div><div class="detailtop">${logo(b)}<div><div class="dtitle">${esc(b.name)}</div><div class="tag">${esc(b.tag)}</div><div class="addr">${esc(b.address)}</div></div></div><div class="heroStat"><div class="heroRow"><div><div class="heroCrowd" style="color:${COLORS[b.lvl]}">${l.label}</div><div class="muted">Likely ${l.range}</div></div><div><div class="heroLine">${b.wait?b.wait+" min":"No line"}</div><div class="muted">est. line</div></div></div><div class="barline"><div style="width:${l.pct}%;background:${COLORS[b.lvl]}"></div></div><div class="conf"><span class="dot" style="background:${confColor(sig.tone)}"></span>${esc(sig.label)} · ${esc(sig.detail)}</div></div>${detailMiniRow(b)}<div class="tabs2"><button class="${detailTab==="live"?"on":""}" onclick="setDetailTab('live')">Live</button><button class="${detailTab==="highlights"?"on":""}" onclick="setDetailTab('highlights')">Highlights</button><button class="${detailTab==="stats"?"on":""}" onclick="setDetailTab('stats')">Intel</button><button class="${detailTab==="events"?"on":""}" onclick="setDetailTab('events')">Events</button></div>${detailPanel(b,reports)}<div class="ctaGrid"><button class="cta" onclick="openMaps(current)"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><path d="M12 21s7-6.1 7-11a7 7 0 0 0-14 0c0 4.9 7 11 7 11z"/><circle cx="12" cy="10" r="2.4"/></svg><span>Directions</span></button><button class="cta" onclick="checkInCurrent()"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><path d="M20 6L9 17l-5-5"/></svg><span>Check in</span><small>Verify nearby</small></button><button class="cta" onclick="openReport()"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg><span>Report</span><small>Update status</small></button></div><a class="cta primary" style="min-height:58px;margin-top:9px" href="${lineLeap(b)}" target="_blank" rel="noopener" onclick="trackAppEvent('${b.id}','lineleap_tap')"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.2"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></svg><span>LineLeap</span><small>Get in faster</small></a>`;wrapDetailContent(el)}
function wrapDetailContent(el){var stage=document.createElement("div");stage.className="detailStage";while(el.firstChild)stage.appendChild(el.firstChild);el.appendChild(stage)}
function setDetailTab(tab){detailTab=tab;renderDetail()}
function confidenceBreakdown(b){var sig=signalState(b),src=(b.sources||[]).slice(0,5),rows=`<div class="confidenceRow"><b>Current read</b><span>${esc(sig.label)}</span></div><div class="confidenceRow"><b>Freshness</b><span>${esc(sig.detail)}</span></div><div class="confidenceRow"><b>Data mode</b><span>${esc(sig.mode)}</span></div><div class="confidenceRow"><b>Recent inputs</b><span>${b.confSignals||0} signals</span></div>`;rows+=src.map(function(s){var t=String(s).toLowerCase(),weight=t.indexOf("owner")>-1?"Highest trust":t.indexOf("venue")>-1||t.indexOf("staff")>-1?"Venue confirmed":t.indexOf("verified")>-1||t.indexOf("scout")>-1?"Verified signal":t.indexOf("report")>-1?"Crowd signal":t.indexOf("historical")>-1||t.indexOf("typical")>-1?"Baseline prior":"Supporting";return '<div class="confidenceRow"><b>'+esc(s)+'</b><span>'+weight+'</span></div>'}).join("");return `<div class="confidenceRows">${rows}</div><p class="rewardFine">LineUp blends staff updates, verified nearby reports, check-ins, app demand, and historical baselines. Higher-trust sources count more, and older signals fade toward a typical read for this time.</p>`}
function normalizeSeedReport(row,i){return{id:"seed_"+i,note:row[1]||"No new reports yet",seed_time:row[2]||"",created_at:null,location_verified:false,local:false,seed:true,author:{name:"Anonymous User",avatar_url:"",anonymous:true}}}
function reportRows(id){var remote=REMOTE_REPORTS[id]||[],seed=(REPORTS[id]||[]).map(normalizeSeedReport);if(remote.length)return remote;if(seed.length)return seed;return[{id:"empty",note:"No recent public reports yet",seed_time:"",created_at:null,location_verified:false,empty:true,author:{name:"LineUp",avatar_url:"",anonymous:false}}]}
function reportInitial(name){var s=String(name||"A").trim();return esc((s[0]||"A").toUpperCase())}
function reportTime(r){if(r.empty)return"";if(r.seed_time)return r.seed_time;if(r.local)return"saved locally";return r.created_at?timeAgo(r.created_at):"just now"}
function reportSummaryText(r){var parts=[];if(r.crowd_level&&LEVELS[r.crowd_level])parts.push(LEVELS[r.crowd_level].label+" crowd");if(Number(r.wait_minutes)>0)parts.push(Number(r.wait_minutes)+" min line");else if(r.crowd_level)parts.push("No line");if(r.location_verified)parts.push("verified nearby");return parts.join(" · ")}
function renderReportRows(reports){return reports.map(function(r,i){var a=r.author||{},name=a.name||"Anonymous User",fallback=r.empty?"var(--surface)":i===0?"var(--packed)":i===1?"var(--busy)":"var(--slow)",avatar=a.avatar_url?'<img src="'+esc(a.avatar_url)+'" alt="">':reportInitial(name),meta=r.empty?"":[reportTime(r),a.anonymous?"anonymous":(r.location_verified?"verified nearby":"public")].filter(Boolean).join(" · "),text=r.note||reportSummaryText(r)||"Useful venue signal";return '<div class="reportrow"><div class="avatar" style="background:'+fallback+'">'+avatar+'</div><div><b>'+esc(name)+' <span class="muted">'+esc(meta)+'</span></b><div class="muted">'+esc(text)+'</div></div><div class="chev">'+SVG.chevRight+'</div></div>'}).join("")}
function detailPanel(b,reports){var sig=signalState(b);if(detailTab==="highlights")return renderHighlights("detail");if(detailTab==="events")return `<div class="card"><b>Tonight at ${esc(b.name)}</b><p class="muted" style="margin-top:8px">${esc(b.event)}</p></div><div class="card"><b>Deal context</b><p class="muted" style="margin-top:8px">Venue tools should verify events before they appear as promoted updates.</p></div>`;if(detailTab==="stats")return `<div class="card"><b>Crowd Level · Daily Average</b><div class="chart">${spark()}</div><div class="row"><span>Momentum</span><b>${cap(b.momentum.replace("_"," "))}</b></div><div class="row"><span>Read quality</span><b style="color:${confColor(sig.tone)}">${esc(sig.label)}</b></div><div class="row"><span>Recent inputs</span><b>${b.confSignals||0}</b></div></div><div class="card"><b>Why this read</b>${confidenceBreakdown(b)}</div>`;return `<div class="card"><b>Live activity</b><p class="muted" style="margin-top:6px">Currently ${b.momentum.replace("_"," ")} near this venue. ${esc(sig.label)} · ${esc(sig.detail)}.</p><div class="chart">${spark()}</div></div><details class="card photoPanel"><summary>Confidence <span class="muted">Why this read</span></summary>${confidenceBreakdown(b)}</details><div class="sectionlabel">RECENT REPORTS</div><div class="card">${renderReportRows(reports)}<button class="field" onclick="loadVenueReports(current.id);showToast('Refreshing live reports')">Refresh reports</button></div>`}
function spark(){return '<svg viewBox="0 0 300 120" preserveAspectRatio="none"><path d="M0,85 C30,65 38,90 58,76 C82,58 90,70 110,50 C135,22 160,35 183,18 C210,4 230,30 252,26 C275,22 284,56 300,50" fill="none" stroke="var(--packed)" stroke-width="4"/><path d="M0,120 L0,85 C30,65 38,90 58,76 C82,58 90,70 110,50 C135,22 160,35 183,18 C210,4 230,30 252,26 C275,22 284,56 300,50 L300,120 Z" fill="rgba(255,79,123,.14)"/></svg>'}
function openReport(){trackAppEvent(current.id,"report_open");selectedReportLevel=current.lvl;$("#reportSheet").classList.add("open");renderReportSheet();capturePresence("report",current.id,true)}
function renderReportSheet(){var b=current,pc=presenceCopy();$("#sheetcard").innerHTML=`<h2>Report ${esc(b.name)}</h2><p class="sheetIntro">Reports help LineUp confirm what is happening right now. Nearby reports carry more weight when location is available.</p><div class="locationStatus"><b>${esc(pc.title)}</b><span>${esc(pc.detail)}</span></div><label class="fieldLabel">Crowd</label><div class="choicegrid">${Object.keys(LEVELS).map(k=>`<button class="${selectedReportLevel===k?"on":""}" onclick="setReportCrowd('${k}')">${LEVELS[k].label}</button>`).join("")}</div><label class="fieldLabel">Line wait</label><div class="choicegrid"><button onclick="setLinePreset(0)">No line</button><button onclick="setLinePreset(5)">5</button><button onclick="setLinePreset(15)">15</button><button onclick="setLinePreset(30)">30+</button></div><input class="field" id="lineField" type="number" min="0" max="90" inputmode="numeric" value="${b.wait||0}" placeholder="Minutes"><label class="fieldLabel">Cover tonight</label><select class="field" id="coverField"><option value="">No cover showing</option><option value="$5">$5 cover</option><option value="$10">$10 cover</option><option value="$15">$15 cover</option><option value="$20">$20 cover</option></select><textarea class="field" id="noteField" placeholder="Optional note: line wrapped, patio calm, DJ just started..." style="height:86px;margin-top:10px"></textarea><div class="sheetActions"><button class="secondaryBtn" onclick="closeSheet()">Cancel</button><button class="submit" onclick="submitReport()">Submit report</button></div>`;$("#coverField").value=b.coverActive?b.cover:""}
function setReportCrowd(level){selectedReportLevel=level;renderReportSheet()}
function setLinePreset(v){var el=$("#lineField");if(el)el.value=v}
function closeSheet(){$("#reportSheet").classList.remove("open")}
async function submitReport(){var v=parseInt($("#lineField").value,10),cover=$("#coverField").value,note=$("#noteField").value.trim(),patch={lvl:selectedReportLevel,wait:isNaN(v)?current.wait:Math.max(0,Math.min(90,v)),fresh:0,conf:"high",momentum:selectedReportLevel==="packed"||selectedReportLevel==="busy"?"heating_up":selectedReportLevel==="dead"?"cooling_down":"steady",sources:["Fresh user report","Recent app activity"],coverActive:!!cover,cover:cover||current.cover},bar=current;saveBarUpdate(bar,patch);closeSheet();var result=await syncReportToSupabase(bar,patch,note,false),reportId=result.report&&result.report.id;if(reportId){await loadVenueReports(bar.id);awardReward(result.verified?"verified_report":"report",bar.name,{report_id:reportId});showToast(result.verified?"Verified report added":"Report added live")}else{showToast("Report could not sync. Try again.")}if(authState)accountRequest("claim",{favorites:favs}).catch(function(){});loadDeviceProfile();renderDetail();renderAll()}
function reportSummary(b,note){var line=b.wait?b.wait+" min line":"no line",crowd=level(b).label.toLowerCase();if(note)return note;return cap(crowd)+" crowd · "+line}
function openAdmin(){setPage("statsPage")}
function renderAdminSheet(){var ids=isOwnerAccount()?activeBars().map(v=>v.id):assignedVenues().map(v=>v.id);ids=ids.filter(function(id){return BARS.some(function(b){return b.id===id})});if(!ids.length){$("#statsPage").innerHTML='<div class="sectionlabel">VENUE CONTROLS</div><div class="card"><b>No venue role found</b><p class="muted intelCopy">This account does not have owner or venue staff access.</p></div>';return}if(!adminVenueId||ids.indexOf(adminVenueId)<0)adminVenueId=defaultControlVenueId()||ids[0];var b=BARS.find(x=>x.id===adminVenueId)||BARS.find(x=>x.id===ids[0]);adminVenueId=b.id;var venueControl=ids.length>1?`<label class="fieldLabel">Venue</label><select class="field" id="adminVenue" onchange="adminVenueId=this.value;renderAdminSheet()">${ids.map(function(id){var v=BARS.find(x=>x.id===id);return '<option value="'+esc(id)+'" '+(id===b.id?"selected":"")+'>'+esc(v?v.name:id)+'</option>'}).join("")}</select>`:`<div class="lockNote">Venue access: ${esc(b.name)} only</div>`;$("#statsPage").innerHTML=`<div class="ownerHeader"><div><div class="sectionlabel">VENUE CONTROLS</div><h2>Staff Live Console</h2></div></div><div class="card"><p class="sheetIntro">Update crowd, line wait, cover, and event notes for venues assigned to your signed-in account. Staff signals carry high trust in the scoring engine.</p><div class="adminVenueHeader">${logo(b)}<div><b>${esc(b.name)}</b><span>${esc(b.address)}</span><span>Current read: ${level(b).label} · ${b.wait?b.wait+" min":"No line"}</span></div></div>${venueControl}<label class="fieldLabel">Crowd</label><div class="choicegrid">${Object.keys(LEVELS).map(k=>`<button class="${b.lvl===k?"on":""}" onclick="adminPatch('${b.id}',{lvl:'${k}',fresh:0,conf:'high',momentum:'${k==="packed"||k==="busy"?"heating_up":k==="dead"?"cooling_down":"steady"}'})">${LEVELS[k].label}</button>`).join("")}</div><label class="fieldLabel">Line + cover</label><div class="adminMini"><input class="field" id="adminWait" type="number" min="0" max="180" value="${b.wait||0}" placeholder="Wait min"><select class="field" id="adminCover"><option value="">No cover</option><option value="$5">$5</option><option value="$10">$10</option><option value="$15">$15</option><option value="$20">$20</option></select></div><label class="fieldLabel">Event</label><input class="field" id="adminEvent" value="${esc(b.event||"")}" placeholder="Tonight's event"><div class="adminRows"><div class="adminRow"><div><b>Publish venue update</b><small>Writes a fresh staff source to Supabase and recalculates confidence.</small></div><button onclick="applyAdminFields('${b.id}')">Publish</button></div><div class="adminRow"><div><b>Reset local view</b><small>Clears saved local overrides for ${esc(b.name)} on this device.</small></div><button onclick="resetAdminVenue('${b.id}')">Reset</button></div></div>${isOwnerAccount()?'<button class="secondaryBtn" style="margin-top:12px" onclick="clearLocalOverrides()">Clear all local overrides</button>':""}</div>`;$("#adminCover").value=b.coverActive?b.cover:""}
function adminPatch(id,patch){if(!canAdminVenue(id))return showToast("That venue is locked");var b=BARS.find(x=>x.id===id);saveBarUpdate(b,patch);if(current&&current.id===id)current=b;syncVenueAdminToSupabase(id).catch(function(err){showToast(err&&err.message?err.message:"Staff update failed")});renderAdminSheet();if(current&&$("#detail").classList.contains("open"))renderDetail()}
function applyAdminFields(id){var b=BARS.find(x=>x.id===id),wait=parseInt($("#adminWait").value,10),cover=$("#adminCover").value,event=$("#adminEvent").value.trim();adminPatch(id,{wait:isNaN(wait)?b.wait:Math.max(0,Math.min(90,wait)),coverActive:!!cover,cover:cover||b.cover,event:event||b.event,fresh:0,conf:"high",sources:["Venue staff control","Fresh manual update"]});showToast("Staff update applied")}
function resetAdminVenue(id){if(!canAdminVenue(id))return showToast("That venue is locked");delete BAR_UPDATES[id];localStorage.setItem("lineup_bar_updates",JSON.stringify(BAR_UPDATES));location.reload()}
function clearLocalOverrides(){if(!isOwnerAccount())return showToast("Owner account required");localStorage.removeItem("lineup_bar_updates");localStorage.removeItem("lineup_local_reports");location.reload()}
function bindMap(){var box=$("#mapBox"),canvas=$("#mapCanvas");if(!box||!canvas)return;function paint(){canvas.style.setProperty("--pan-x",mapPan.x+"px");canvas.style.setProperty("--pan-y",mapPan.y+"px")}paint();box.onpointerdown=function(e){mapPan.drag=true;mapPan.sx=e.clientX;mapPan.sy=e.clientY;mapPan.ox=mapPan.x;mapPan.oy=mapPan.y;box.setPointerCapture(e.pointerId)};box.onpointermove=function(e){if(!mapPan.drag)return;mapPan.x=Math.max(-110,Math.min(110,mapPan.ox+e.clientX-mapPan.sx));mapPan.y=Math.max(-110,Math.min(110,mapPan.oy+e.clientY-mapPan.sy));paint()};box.onpointerup=box.onpointercancel=function(){mapPan.drag=false}}
function renderAll(){renderRoleTabs();if(!authState)return renderAccountGate();if(accountNeedsSetup())return renderSetupGate();if(active==="statsPage"&&!canUseVenueControls())active="livePage";document.body.dataset.page=active;$all(".page").forEach(p=>p.classList.toggle("active",p.id===active));$all(".navbtn").forEach(n=>n.classList.toggle("on",n.dataset.page===active));if(active==="livePage")renderLive();if(active==="mapPage")renderMap();if(active==="highlightsPage")renderHighlightsPage();if(active==="statsPage"){if(isOwnerAccount())renderOwnerDashboard();else renderAdminSheet()}if(active==="profilePage")renderProfile()}
